{
  "reports": {
    "report_1": {
      "text": "Cedar United beat Vale City 2–1 on Sunday. Sam Lee scored the winner in the 84th minute."
    }
  }
}

{
  "reports": {
    "report_1": {
      "text": "Cedar United denied agreeing a fee for Alex Stone. A club spokesperson said discussions had not begun."
    },
    "report_2": {
      "text": "Cedar United agreed a fee for Alex Stone, City Wire reports, citing an unnamed source. The club has not confirmed the report."
    }
  }
}

{
  "reports": {
    "report_1": {
      "text": "Cedar United said goalkeeper Kim Park will miss the next match with an ankle injury. No return date was given."
    },
    "report_2": {
      "text": "Cedar United appointed Jo Vale as head coach on Monday. Her contract lasts two years."
    },
    "report_3": {
      "text": "Cedar United won 2–1 against Vale City on Sunday."
    }
  }
}
